// The signing-page client (app.md §2.1 items 2-4, row A1.2, app.md:1435): the app's only way to SIGN_HOST. It mounts
// one hidden iframe of SIGN_HOST's release URL, waits for the page's `ready` and then for that frame's first `state`
// answer (READY: the state is known, BAR-09, app.md:1107), and then sends the seventeen kinds of messages.ts and reads
// their answers. Every message from the page is dropped, with no change, unless its `origin` is SIGN_HOST's exactly,
// its `source` is the current iframe's window, its shape passes the schema of what it claims to be (schema.ts), and an
// answer's id is one this client is waiting for. The app never re-sends a kind on its own (APU-03, app.md:1328).
//
// How a request ends without the page's answer:
//   - `signpage_down`: it was never posted (the client was down, or went down before the handshake it waited for);
//   - `client_timeout`: it was posted and the page may have it. Its timeout passed, or the frame went down or was
//     replaced while it was open. The page may still run it, so a screen reads the outcome from `state` (asked again
//     at the next READY) and never re-taps it as unsent.
// Down: no ready in 5 s, no state answer within 5 s of the ready, an iframe error, the iframe's load with no ready
// within 1 s (a refused, failed or blocked load shows the browser's error page and fires load, not error), or an open
// kind's timeout. While down, a fresh iframe is tried after 1 s, then 2, 4 and 8 s, then every SIGNPAGE_RETRY_MS, and
// at once when the browser is back online or the page is shown again; these tries keep the down state until one
// reaches READY, so the down state clears with no reload when SIGN_HOST returns. A ready
// with an `api` this client does not speak is the update state (CH-146): money off until a reload, no retry.
//
// Parent mode (mode "parent"): the app runs framed inside SIGN_HOST's shell, the top window, since WebKit partitions a
// framed SIGN_HOST's storage by the top origin. The client mounts no iframe: it posts to host.parent with SIGN_HOST's
// origin, and a message counts only from host.parent. The shell posts its ready on each load of the app's frame, so an
// app creates its client in its entry module, before its load ends. Down is the same minus the iframe's error and load.
// A retry has no frame to replace: once the shell's ready has been seen, it asks `state` again and READY is that answer;
// before it, it waits SIGNPAGE_HANDSHAKE_MS for a ready. Everything else is the iframe mode's, so an app sees the same
// snapshots and outcomes in both.
//
// Kit version (card kit-frame-version): before each handshake `state` request the client posts a hello naming
// SIGNPAGE_KIT_VERSION (messages.ts HelloMessage), so the page sends it only what this version reads; a page of an
// earlier release drops the hello unanswered. A state's op this client cannot read is left out, never the whole state.

import { OPEN_KINDS, SIGNPAGE_KIT_VERSION } from "./messages.ts";
import type { BuyRoute, HelloMessage, ErrorCode, SignpageKind, SignpageParams, SignpageRequest, SignpageResults, SignpageState, Stage } from "./messages.ts";
import {
  SIGNPAGE_MAX_REQUEST_BYTES,
  SIGNPAGE_PARAM_SCHEMAS,
  SIGNPAGE_RESULT_SCHEMAS,
  signpageAnswerErrorSchema,
  signpageAnswerOkSchema,
  signpageIsKind,
  signpageIsPlainMessage,
  signpageProgressRouteSchema,
  signpageProgressSchema,
  signpageReadableOps,
  signpageReadySchema,
  signpageStateEventSchema,
} from "./schema.ts";
import { deepFreeze } from "../freeze.ts";

export { SIGNPAGE_MAX_ANSWER_BYTES, SIGNPAGE_MAX_ARRAY, SIGNPAGE_MAX_DEPTH, SIGNPAGE_MAX_REQUEST_BYTES } from "./schema.ts";

/** The `api` of messages.ts, the only one this client speaks. */
export const SIGNPAGE_CLIENT_API = 1;
/** No `ready` in this long after the mount, or no `state` answer this long after the ready, and the client is down. */
export const SIGNPAGE_HANDSHAKE_MS = 5_000;
/** While down, a fresh iframe at least this often (the longest wait of the retry backoff). */
export const SIGNPAGE_RETRY_MS = 10_000;
/** The first retry's wait after the client goes down; each next wait doubles, up to the retry option. */
const RETRY_FIRST_MS = 1_000;
/** After the iframe's load, how long a `ready` may still take before the client is down (BAR-09's warm answer, 1 s). */
const LOAD_GRACE_MS = 1_000;

/** How long the client waits for each kind's answer (app.md §2.1 item 3's table); null: no timeout. */
export const SIGNPAGE_TIMEOUT_MS = {
  "deposit.quote": 15_000,
  "deposit.confirm": 15_000,
  arm: 5_000,
  buy: 10_000,
  hop: 10_000,
  "orders.set": 15_000,
  "orders.cancel": 15_000,
  return: 15_000,
  "withdraw.open": 5_000,
  "signin.open": 5_000,
  "backup.open": 5_000,
  "export.open": 5_000,
  signout: 5_000,
  // restore reports `progress` at least every 10 s; a screen shows it stalled, the client never ends it
  restore: null,
  state: 5_000,
  // the shell's (card signpage-shell): answered at once
  nav: 5_000,
  reload: 5_000,
  // the pool kinds (card signpage-pool-kinds): answered once signed and sent, as buy is; the withdraw screen as an open
  "pool.deposit": 10_000,
  "pool.buy": 10_000,
  "pool.sell": 10_000,
  "pool.withdraw": 5_000,
  // the deposit sheet's reads (card kit-deposit-assets-dry): each waits for the helper's 1Click round trips, as
  // deposit.quote does (deposit.assets asks the token list, then one dry quote per asset at once)
  "deposit.assets": 15_000,
  "deposit.dry": 15_000,
  // a pool's deposit address (card pool-deposit-address): with an origin asset, the helper's 1Click round trip, as
  // deposit.quote
  "pool.address": 15_000,
} as const satisfies Record<SignpageKind, number | null>;
deepFreeze(SIGNPAGE_TIMEOUT_MS);

/** After one of these times out, the client asks `state` again (a new `state` request); the kind itself is never re-sent. */
const REASK_STATE: ReadonlySet<SignpageKind> = new Set(["deposit.confirm", "arm", "buy", "hop", "orders.set", "orders.cancel", "return", "pool.deposit", "pool.buy", "pool.sell"]);

/** The hidden iframe's attributes (app.md §2.1 item 2; AX-06, app.md:1386). */
export const SIGNPAGE_IFRAME_ATTRIBUTES = {
  sandbox: "allow-scripts allow-same-origin",
  allow: "",
  referrerpolicy: "no-referrer",
  "aria-hidden": "true",
  tabindex: "-1",
  width: "0",
  height: "0",
} as const;
deepFreeze(SIGNPAGE_IFRAME_ATTRIBUTES);

/** The codes the client itself answers with, never the page. */
export const SIGNPAGE_CLIENT_CODES = { timeout: "client_timeout", down: "signpage_down" } as const;
deepFreeze(SIGNPAGE_CLIENT_CODES);

/** "update": the page speaks an `api` this client does not (CH-146); money stays off until a reload. */
export type SignpageClientStatus = "connecting" | "ready" | "down" | "update";
export type SignpageDropReason = "origin" | "source" | "shape" | "id";

/** Read-only, and frozen at run time: every caller shares one snapshot per change (card oneclick-fee-path-own-key). */
export interface SignpageClientSnapshot {
  readonly status: SignpageClientStatus;
  /** The page's release tag from its handshake. */
  readonly release: string | null;
  /** The last state the page sent. */
  readonly state: SignpageState | null;
  /** True when `state` is not this frame's latest: a `state` request timed out, or the frame went down or was replaced. */
  readonly stale: boolean;
}

export type SignpageOutcome<K extends SignpageKind = SignpageKind> =
  | { ok: true; result: SignpageResults[K] }
  | { ok: false; error: { code: ErrorCode } };

/** A request: its id at once (to match `progress` events), its outcome later. */
export interface SignpageRequestHandle<K extends SignpageKind = SignpageKind> {
  id: string;
  outcome: Promise<SignpageOutcome<K>>;
}

/** The parts of the browser the client uses; a test passes its own. */
export interface SignpageClientHost {
  window: Pick<Window, "addEventListener" | "removeEventListener">;
  /** Unused in parent mode. */
  document: Pick<Document, "createElement">;
  /** Where the iframe goes; unused in parent mode. */
  mount: Pick<HTMLElement, "appendChild">;
  /** Parent mode: the shell's window, the app's window.parent. */
  parent?: Pick<Window, "postMessage">;
}

/** "iframe": a hidden iframe of SIGN_HOST (the default). "parent": the app runs inside SIGN_HOST's shell. */
export type SignpageClientMode = "iframe" | "parent";

export interface SignpageClientOptions {
  /** SIGN_HOST's release URL, for example "https://confidential.unrealized.trade/": https, no query, no fragment. */
  url: string;
  host: SignpageClientHost;
  /** 0 turns the retry off. */
  retryMs?: number;
  mode?: SignpageClientMode;
}

export interface SignpageClient {
  snapshot(): SignpageClientSnapshot;
  /** Called on every change of the snapshot; returns the unsubscribe. */
  subscribe(fn: (s: SignpageClientSnapshot) => void): () => void;
  /** Called on every `progress` event; returns the unsubscribe. */
  onProgress(fn: (id: string, stage: Stage) => void): () => void;
  /** Called on every route event of a running buy (messages.ts BuyRoute), by the request's id; returns the unsubscribe.
   *  A page of an earlier release sends none. */
  onRoute(fn: (id: string, route: BuyRoute) => void): () => void;
  /** Sends one request once READY. Throws at once when its params are not exactly its kind's. */
  request<K extends SignpageKind>(kind: K, params: SignpageParams[K]): SignpageRequestHandle<K>;
  /** A fresh iframe (parent mode: none) and a new handshake now. */
  retry(): void;
  /** Messages dropped so far, by why. */
  dropped(): Record<SignpageDropReason, number>;
  destroy(): void;
}

/**
 * The request envelope of a kind, built from exactly its allowed params. Throws on an unknown kind, a bad param or a
 * request over SIGNPAGE_MAX_REQUEST_BYTES.
 */
export function signpageBuildRequest<K extends SignpageKind>(kind: K, params: SignpageParams[K], id: string): SignpageRequest<K> {
  if (!signpageIsKind(kind)) throw new TypeError(`signpage: no such kind ${String(kind)}`);
  // the request's own copy, taken before the check: what is checked is what is posted, whatever the caller does to its
  // params after (card oneclick-fee-path-own-key; the client posts after the handshake, which can be seconds later)
  let own: SignpageParams[K];
  try {
    own = structuredClone(params);
  } catch {
    throw new TypeError(`signpage: params are not exactly ${kind}'s`);
  }
  if (!SIGNPAGE_PARAM_SCHEMAS[kind](own)) throw new TypeError(`signpage: params are not exactly ${kind}'s`);
  const msg = { ...own, v: 1, id, type: kind } as SignpageRequest<K>;
  if (new TextEncoder().encode(JSON.stringify(msg)).length > SIGNPAGE_MAX_REQUEST_BYTES) {
    throw new TypeError(`signpage: ${kind} is over ${SIGNPAGE_MAX_REQUEST_BYTES} bytes`);
  }
  return msg;
}

/** SIGN_HOST's origin from its release URL; throws on anything but https with no query, fragment or credentials. */
export function signpageOrigin(url: string): string {
  const u = new URL(url);
  if (u.protocol !== "https:" || u.search || u.hash || u.username || u.password || u.href !== url) {
    throw new TypeError(`signpage: ${url} is not an https release URL with no query`);
  }
  return u.origin;
}

type Timer = ReturnType<typeof setTimeout>;

interface Pending {
  kind: SignpageKind;
  resolve: (o: SignpageOutcome) => void;
  timer: Timer | null;
}

/** A fresh outcome each call (card kit-oneclick-pins-frozen review): one shared object handed to every caller would let
 *  one caller's write change the answer another caller reads. */
const DOWN = () => ({ ok: false, error: { code: SIGNPAGE_CLIENT_CODES.down } }) as const;
const TIMEOUT = () => ({ ok: false, error: { code: SIGNPAGE_CLIENT_CODES.timeout } }) as const;

export function createSignpageClient(opts: SignpageClientOptions): SignpageClient {
  const origin = signpageOrigin(opts.url);
  const { host } = opts;
  const retryMs = opts.retryMs ?? SIGNPAGE_RETRY_MS;
  const mode: unknown = opts.mode === undefined ? "iframe" : opts.mode;
  if (mode !== "iframe" && mode !== "parent") throw new TypeError(`signpage: no such mode ${String(mode)}`);
  /** Parent mode's shell window; null in the iframe mode. */
  const shell = mode === "parent" ? (host.parent ?? null) : null;
  if (mode === "parent" && (shell === null || shell === (host.window as unknown))) {
    throw new TypeError("signpage: parent mode needs host.parent, a window other than host.window");
  }

  let snap: SignpageClientSnapshot = { status: "connecting", release: null, state: null, stale: false };
  const listeners = new Set<(s: SignpageClientSnapshot) => void>();
  const progressListeners = new Set<(id: string, stage: Stage) => void>();
  const routeListeners = new Set<(id: string, route: BuyRoute) => void>();
  /** Posted requests, by id. */
  const pending = new Map<string, Pending>();
  const drops: Record<SignpageDropReason, number> = { origin: 0, source: 0, shape: 0, id: 0 };
  /** Requests not posted yet, waiting for the handshake to end. */
  let waiters: (() => void)[] = [];
  let frame: HTMLIFrameElement | null = null;
  /** The frame's generation: a handshake answer of an older frame changes nothing. */
  let gen = 0;
  let handshakeTimer: Timer | null = null;
  let retryTimer: Timer | null = null;
  /** The current frame's wait for its ready after its load. */
  let loadTimer: Timer | null = null;
  /** True once the current frame has sent its ready (the iframe mode only). */
  let readySeen = false;
  /** The newest handshake `state` request: only its failure is down (a repeated ready asks again). */
  let ask = 0;
  /** Retries since the client was last READY: the backoff's step. */
  let tries = 0;
  let destroyed = false;

  /** What every caller gets: one deep-frozen copy of `snap` per change, the same object from snapshot(), to every
   *  listener and as a state request's result until the next change (card oneclick-fee-path-own-key). Stable between
   *  changes, as useSyncExternalStore needs; a write throws; and none of it is `snap`, which the client reads to decide
   *  whether a request may go. */
  let view: SignpageClientSnapshot = deepFreeze(structuredClone(snap));
  /** Calls every listener in `fns` with `args`, each on its own: a listener's throw (a write into its frozen snapshot
   *  among them) stops no other listener and none of the client's own steps around the call, and is reported after, on
   *  its own microtask, as a browser reports an event listener's error (card oneclick-fee-path-own-key, delta review).
   *  The list is the one at the change's start, so a listener added during it hears the next change; and a listener
   *  removed during it (an unsubscribe, or a destroy) is skipped, as EventTarget skips a removed listener (review r3). */
  const tell = <A extends unknown[]>(fns: ReadonlySet<(...a: A) => void>, ...args: A): void => {
    for (const f of [...fns]) {
      if (!fns.has(f)) continue;
      try {
        f(...args);
      } catch (e) {
        queueMicrotask(() => {
          throw e;
        });
      }
    }
  };
  const set = (patch: Partial<SignpageClientSnapshot>) => {
    snap = { ...snap, ...patch };
    view = deepFreeze(structuredClone(snap));
    // the client keeps the view's frozen state, never an object from a message or a caller
    snap = { ...snap, state: view.state };
    if (snap.status !== "connecting") {
      const w = waiters;
      waiters = [];
      for (const f of w) f();
    }
    tell(listeners, view);
  };

  const clearTimer = (t: Timer | null) => {
    if (t !== null) clearTimeout(t);
  };

  /** Where requests go and the only source a message counts from: the shell, or the current iframe's window. */
  const peer = () => shell ?? frame?.contentWindow ?? null;

  const settle = (id: string, outcome: SignpageOutcome) => {
    const p = pending.get(id);
    if (!p) return;
    pending.delete(id);
    clearTimer(p.timer);
    p.resolve(outcome);
  };

  /** Every posted request ends as client_timeout: the page may have it, so it is never reported unsent. */
  const endPosted = () => {
    for (const id of [...pending.keys()]) settle(id, TIMEOUT());
  };

  /** The frame is gone or unusable: the state it sent is no longer fresh. */
  const leave = (status: SignpageClientStatus) => {
    clearTimer(handshakeTimer);
    handshakeTimer = null;
    clearTimer(loadTimer);
    loadTimer = null;
    endPosted();
    set({ status, stale: snap.state !== null || snap.stale });
  };

  const down = () => {
    if (destroyed || snap.status === "update") return;
    leave("down");
    // a "down" listener may have destroyed the client: then no retry is set
    if (destroyed) return;
    if (retryMs > 0 && retryTimer === null) {
      const wait = Math.min(RETRY_FIRST_MS * 2 ** tries, retryMs);
      tries++;
      retryTimer = setTimeout(() => {
        retryTimer = null;
        mountFrame(true);
      }, wait);
    }
  };

  /** Back online, or the page shown again: while down, a fresh iframe now and the backoff from its start. */
  const wake = (ev: Event) => {
    if (destroyed || snap.status !== "down") return;
    if (ev.type === "visibilitychange" && (ev.target as Partial<Document> | null)?.visibilityState === "hidden") return;
    tries = 0;
    mountFrame(true);
  };

  const toUpdate = () => {
    clearTimer(retryTimer);
    retryTimer = null;
    leave("update");
  };

  /** No ready within SIGNPAGE_HANDSHAKE_MS from now: down. */
  const waitReady = () => {
    clearTimer(handshakeTimer);
    handshakeTimer = setTimeout(() => {
      handshakeTimer = null;
      if (snap.status !== "ready") down();
    }, SIGNPAGE_HANDSHAKE_MS);
  };

  /**
   * A fresh iframe and its handshake (parent mode: a `state` request to the same shell at once, which answers at any
   * time; its ready comes only when it loads the frame, so a client made after that load or a slow load must not wait
   * for one); `quiet`: a retry of the client's own, which keeps the down state until READY.
   */
  const mountFrame = (quiet = false) => {
    if (destroyed || snap.status === "update") return;
    clearTimer(retryTimer);
    retryTimer = null;
    // an answer to the old frame can never pass the source check, so its requests end now, as client_timeout (parent
    // mode: they end the same way, so both modes answer alike, and a late answer is dropped by its id)
    endPosted();
    gen++;
    if (shell !== null) {
      if (!(quiet && snap.status === "down")) set({ status: "connecting", stale: snap.state !== null || snap.stale });
      return askState();
    }
    readySeen = false;
    clearTimer(loadTimer);
    loadTimer = null;
    frame?.remove();
    const f = host.document.createElement("iframe");
    for (const [k, v] of Object.entries(SIGNPAGE_IFRAME_ATTRIBUTES)) f.setAttribute(k, v);
    // set through the CSSOM, which a CSP with no 'unsafe-inline' style allows
    f.style.position = "absolute";
    f.style.width = "0";
    f.style.height = "0";
    f.style.border = "0";
    f.style.visibility = "hidden";
    f.addEventListener("error", () => f === frame && down());
    // the page posts its ready as it starts, before its load (the message can land just after the load event); a load
    // with no ready within 1 s is the browser's error page
    f.addEventListener("load", () => {
      if (f !== frame || readySeen || loadTimer !== null) return;
      loadTimer = setTimeout(() => {
        loadTimer = null;
        if (f === frame && !readySeen) down();
      }, LOAD_GRACE_MS);
    });
    f.src = opts.url;
    frame = f;
    waitReady();
    if (!(quiet && snap.status === "down")) set({ status: "connecting", stale: snap.state !== null || snap.stale });
    host.mount.appendChild(f);
  };

  /** Posts a built request to the current frame and waits for its answer, its timeout or the frame's end. */
  const post = <K extends SignpageKind>(msg: SignpageRequest<K>, timeoutMs: number | null, onTimeout: () => void): Promise<SignpageOutcome<K>> => {
    const win = peer();
    if (destroyed || !win) return Promise.resolve(DOWN());
    return new Promise<SignpageOutcome<K>>((resolve) => {
      const timer =
        timeoutMs === null
          ? null
          : setTimeout(() => {
              if (!pending.has(msg.id)) return;
              settle(msg.id, TIMEOUT());
              onTimeout();
            }, timeoutMs);
      pending.set(msg.id, { kind: msg.type, resolve: resolve as (o: SignpageOutcome) => void, timer });
      win.postMessage(msg, origin);
    });
  };

  /** The kit version, named to the page before each handshake `state` request (messages.ts HelloMessage). */
  const hello = () => {
    const win = peer();
    if (destroyed || !win) return;
    const msg: HelloMessage = { v: 1, type: "hello", kit: SIGNPAGE_KIT_VERSION };
    win.postMessage(msg, origin);
  };

  const onReady = (msg: { release: string; api: number }) => {
    if (msg.api !== SIGNPAGE_CLIENT_API) return toUpdate();
    clearTimer(retryTimer);
    retryTimer = null;
    readySeen = true;
    clearTimer(loadTimer);
    loadTimer = null;
    set({ release: msg.release });
    if (snap.status === "ready") {
      // a ready again is a page that started again: it reads this client as kit-v1.4 until told
      hello();
      void client.request("state", {});
      return;
    }
    askState();
  };

  /**
   * READY is this frame's first `state` answer, within SIGNPAGE_HANDSHAKE_MS of its ready (parent mode: of the client's
   * start, a retry or a ready). Any of this frame's asks may bring READY; only the newest one's failure is down.
   */
  const askState = () => {
    clearTimer(handshakeTimer);
    handshakeTimer = null;
    const g = gen;
    const a = ++ask;
    hello();
    const msgState = signpageBuildRequest("state", {}, crypto.randomUUID());
    void post(msgState, SIGNPAGE_HANDSHAKE_MS, () => {}).then((o) => {
      if (g !== gen || destroyed || snap.status === "update") return;
      if (o.ok) {
        tries = 0;
        if (snap.status !== "ready") set({ status: "ready" });
      } else if (a === ask && snap.status !== "ready") down();
    });
  };

  const onMessage = (ev: MessageEvent) => {
    if (ev.origin !== origin) return void drops.origin++;
    const from = peer();
    if (from === null || ev.source !== from) return void drops.source++;
    const data: unknown = ev.data;
    if (!signpageIsPlainMessage(data)) return void drops.shape++;
    const m = data as Record<string, unknown>;
    if (Object.hasOwn(m, "ok")) {
      const p = typeof m.id === "string" ? pending.get(m.id) : undefined;
      if (!p) return void drops.id++;
      // a state's op this client cannot read is left out, never the whole state (card kit-frame-version)
      const result = signpageAnswerOkSchema(m) ? (p.kind === "state" ? signpageReadableOps(m.result) : m.result) : undefined;
      if (result !== undefined && SIGNPAGE_RESULT_SCHEMAS[p.kind](result)) {
        if (p.kind === "state") {
          set({ state: result as SignpageState, stale: false });
          return settle(m.id as string, { ok: true, result: view.state as SignpageResults[SignpageKind] });
        }
        return settle(m.id as string, { ok: true, result: result as SignpageResults[SignpageKind] });
      }
      if (signpageAnswerErrorSchema(m)) return settle(m.id as string, { ok: false, error: m.error as { code: ErrorCode } });
      return void drops.shape++;
    }
    if (signpageReadySchema(m)) return onReady(m as { release: string; api: number });
    if (snap.status !== "ready") return void drops.shape++;
    if (m.type === "state" && Object.hasOwn(m, "state")) {
      const ev = { ...m, state: signpageReadableOps(m.state) };
      if (signpageStateEventSchema(ev)) return set({ state: ev.state as SignpageState, stale: false });
    }
    if (signpageProgressSchema(m)) {
      tell(progressListeners, m.id as string, m.stage as Stage);
      return;
    }
    if (signpageProgressRouteSchema(m)) {
      const { v: _v, type: _t, id, ...route } = m;
      // frozen as the snapshot is: listeners share one route object, and a write into it throws
      tell(routeListeners, id as string, deepFreeze(route) as BuyRoute);
      return;
    }
    drops.shape++;
  };

  const onTimeout = (kind: SignpageKind) => {
    if ((OPEN_KINDS as readonly SignpageKind[]).includes(kind)) return down();
    if (kind === "state") return set({ stale: true });
    if (REASK_STATE.has(kind)) void client.request("state", {});
  };

  const client: SignpageClient = {
    snapshot: () => view,
    subscribe(fn) {
      listeners.add(fn);
      return () => void listeners.delete(fn);
    },
    onProgress(fn) {
      progressListeners.add(fn);
      return () => void progressListeners.delete(fn);
    },
    onRoute(fn) {
      routeListeners.add(fn);
      return () => void routeListeners.delete(fn);
    },
    request(kind, params) {
      const id = crypto.randomUUID();
      const msg = signpageBuildRequest(kind, params, id);
      const outcome = (async () => {
        if (snap.status === "connecting" && !destroyed) await new Promise<void>((r) => waiters.push(r));
        // parent mode's update state: the shell still answers `reload` (it reloads the top window, shell and app)
        const reloadInUpdate = shell !== null && kind === "reload" && snap.status === "update";
        if (destroyed || (snap.status !== "ready" && !reloadInUpdate)) return DOWN();
        return post(msg, SIGNPAGE_TIMEOUT_MS[kind], () => onTimeout(kind));
      })();
      return { id, outcome };
    },
    retry() {
      tries = 0;
      mountFrame();
    },
    dropped: () => ({ ...drops }),
    destroy() {
      if (destroyed) return;
      // destroyed first: a "down" listener that destroys again returns at once, and down() sets no retry after it
      destroyed = true;
      clearTimer(retryTimer);
      retryTimer = null;
      leave("down");
      host.window.removeEventListener("message", onMessage);
      host.window.removeEventListener("online", wake);
      host.window.removeEventListener("visibilitychange", wake);
      frame?.remove();
      frame = null;
      listeners.clear();
      progressListeners.clear();
      routeListeners.clear();
    },
  };

  host.window.addEventListener("message", onMessage);
  host.window.addEventListener("online", wake);
  host.window.addEventListener("visibilitychange", wake);
  mountFrame();
  return client;
}

packages/kit/src/signpage/wallets.ts.body:
// Every address that holds the user's money (card app-export-every-wallet), from the signing page's state alone, so an
// app can put an export (export.open, by chain and address) on each one and no money is left on a wallet the user
// cannot take out. Addresses only: the key is shown only on SIGN_HOST's own export screen.
import { CHAINS } from "../orders/record.ts";
import type { Chain } from "../orders/record.ts";
import type { SignpageState, WalletState } from "./messages.ts";

/** One wallet of this seed that holds money. */
export interface MoneyWallet {
  chain: Chain;
  address: string;
  /** "trade": a fresh or hop wallet (a position's, or one armed, ready or returning); "deposit": a deposit wallet with money left. */
  role: "trade" | "deposit";
  /** The tokens of the user's open positions this wallet holds, in the state's order. */
  tokens: string[];
}

/** The wallet states with money on the wallet or on its way to it: never PLANNED (nothing sent yet) or EMPTY. */
const FUNDED: ReadonlySet<WalletState> = new Set(["ARMING", "READY", "IN_POSITION", "RETURNING"]);

/** A decimal string above zero. */
const aboveZero = (s: string): boolean => /[1-9]/.test(s);

/**
 * Every address of `s` that holds money, each (chain, address) once: every wallet an open position names, every fresh
 * or hop wallet that is armed, ready, in a position or returning, and every deposit wallet with money left. By chain
 * (CHAINS' order), then trade wallets before deposit wallets, each in the state's own order (positions' wallets first).
 */
export function moneyWallets(s: SignpageState): MoneyWallet[] {
  const seen = new Map<string, MoneyWallet>();
  const add = (chain: Chain, address: string, role: MoneyWallet["role"]): MoneyWallet => {
    const k = `${chain}\n${address}`;
    let w = seen.get(k);
    if (!w) seen.set(k, (w = { chain, address, role, tokens: [] }));
    return w;
  };
  for (const p of s.positions) {
    for (const a of p.wallets) {
      const w = add(p.chain, a, "trade");
      if (!w.tokens.includes(p.token)) w.tokens.push(p.token);
    }
  }
  for (const w of s.wallets) if (FUNDED.has(w.state)) add(w.chain, w.address, "trade");
  for (const d of s.deposit_wallets ?? []) if (aboveZero(d.amount)) add(d.chain, d.address, "deposit");
  const all = [...seen.values()];
  const rank = (w: MoneyWallet) => CHAINS.indexOf(w.chain as (typeof CHAINS)[number]) * 2 + (w.role === "trade" ? 0 : 1);
  return all.map((w, i) => ({ w, i })).sort((a, b) => rank(a.w) - rank(b.w) || a.i - b.i).map((x) => x.w);
}

packages/kit/src/vault/messages.ts.body:
// The vault module's messages (card vault-kit-messages; the vault paper V4.1 and 7.1, docs/plan1/vault.md l.1230 and
// l.1257-1259): the one deposit call and its storage prepay here, the withdrawal request in request.ts. Both build
// only from the frozen shapes (shapes.ts) and add no field to them.
//
// - One deposit call for every mover. The deposit's id U, a return id R, a refund id V (and A's move back to the
//   vault) all move money in the same way: the moving NEAR-implicit account's own TOKEN.ft_transfer_call(vault,
//   amount, msg) with 1 yocto and 180 Tgas, signed by that account as a NEP-366 DelegateAction (VAULT_DEPOSIT_CARRIER,
//   VAULT_DEPOSIT_SIGNERS). So there is one builder, and the depositor is the mover itself: the message's depositor
//   and the delegate's sender_id come from one argument and cannot differ.
// - The call is the unsigned part of the helper's HelperBindDeposit (helper/v1.ts): sender_id, receiver_id and the one
//   FunctionCall action, written as POST /v1/bind decodes it. The signer adds nonce, max_block_height and public_key.
// - The amount is refused where the vault would refuse it (2.5.1 rows 4-5): under MIN_DEPOSIT, or not below u128::MAX,
//   and above the beta cap HELPER_BIND_DEPOSIT_CAP, which the relayer also refuses: the device never signs a deposit
//   the relayer will not carry. The cap is read from that one constant, so lifting it changes one line.
// - The vault refuses a depositor equal to itself (2.5.1 row 2) and the relayer refuses it too, so a 64-hex vault equal
//   to the mover is refused here; so is intents.near as the vault, since the vault's balance rests outside it.
// - The prepay keys the same canonical decimal as the message, so a prepay and its deposit name one record (2.5.1). It
//   takes a byte count: VAULT_STORAGE_PREPAY.min_bytes (756) or bytes_when_a_tree_may_grow (904) on a new record, and
//   any amount on a record that exists, such as the 148-byte top-up when a tree may grow after the first prepay.
import { HELPER_BIND_DEPOSIT_CAP, type HelperFtTransferCallArgs, type HelperFunctionCall } from "../helper/v1.ts";
import {
  VAULT_CONSTANTS,
  VAULT_DEPOSIT_CARRIER,
  VAULT_FIELD_P,
  VAULT_STORAGE_BYTE_COST,
  VAULT_STORAGE_PREPAY,
  vaultAccountId,
  vaultDepositMessage,
} from "./shapes.ts";

export * from "./request.ts";

const TGAS = 1_000_000_000_000;
const U128_MAX = (1n << 128n) - 1n;

/** What a move into the vault needs: the vault, its token, the moving id (64 hex), the amount and the note's precommitment. */
export type VaultDepositCallArgs = {
  vault: string;
  token: string;
  /** The moving NEAR-implicit id (U, R, V or A): the delegate's signer and the message's depositor. */
  mover: string;
  /** In the token's base units. */
  amount: bigint;
  precommitment: bigint;
};

/** The deposit delegate before it is signed: the mover's one ft_transfer_call on the token. */
export type VaultDepositCall = {
  sender_id: string;
  receiver_id: string;
  actions: [HelperFunctionCall<"ft_transfer_call", HelperFtTransferCallArgs>];
};

/**
 * The one deposit call, the same for U, R, V and A: mover's TOKEN.ft_transfer_call(vault, amount,
 * vaultDepositMessage(precommitment, mover)), 1 yocto, 180 Tgas. Refuses a vault or token that is not a NEAR account
 * id or names the other, intents.near as the vault, a mover that is not a lowercase 64-hex NEAR-implicit id or is the
 * vault, a precommitment not below p, an amount that is not a bigint, under MIN_DEPOSIT, over HELPER_BIND_DEPOSIT_CAP
 * or not below u128::MAX.
 */
export function vaultDepositCall(a: VaultDepositCallArgs): VaultDepositCall {
  const vault = vaultAccountId(a.vault, "vault");
  const token = vaultAccountId(a.token, "token");
  if (vault === token) throw new Error("vault: the token");
  if (vault === VAULT_CONSTANTS.INTENTS) throw new Error("vault: intents.near");
  if (a.mover === vault) throw new Error("mover: the vault");
  if (typeof a.amount !== "bigint") throw new Error("amount: not a bigint");
  if (a.amount < VAULT_CONSTANTS.MIN_DEPOSIT) throw new Error("amount: under MIN_DEPOSIT");
  if (a.amount > HELPER_BIND_DEPOSIT_CAP) throw new Error("amount: over HELPER_BIND_DEPOSIT_CAP");
  // The vault's own bound, which holds once the beta cap is lifted.
  if (a.amount >= U128_MAX) throw new Error("amount: not below u128::MAX");
  const msg = vaultDepositMessage(a.precommitment, a.mover);
  return {
    sender_id: a.mover,
    receiver_id: token,
    actions: [
      {
        FunctionCall: {
          method_name: VAULT_DEPOSIT_CARRIER.method,
          args: { receiver_id: vault, amount: a.amount.toString(), msg },
          gas: VAULT_DEPOSIT_CARRIER.gas_tgas * TGAS,
          deposit: "1",
        },
      },
    ],
  };
}

/** The storage prepay a deposit needs first, by anyone (the relayer): vault.storage_prepay({precommitment}). */
export type VaultStoragePrepay = {
  receiver_id: string;
  method: typeof VAULT_STORAGE_PREPAY.method;
  args: { precommitment: string };
  deposit_yocto: bigint;
};

/**
 * storage_prepay(precommitment) on the vault, attaching `bytes` × VAULT_STORAGE_BYTE_COST. The precommitment is written
 * as the deposit message writes it, in 1..p-1 as the vault takes it (0 refused, vault review R-01). bytes is a positive
 * whole number; the vault refuses under min_bytes on a new record.
 */
export function vaultStoragePrepay(vault: string, precommitment: bigint, bytes: number): VaultStoragePrepay {
  if (typeof precommitment !== "bigint" || precommitment <= 0n || precommitment >= VAULT_FIELD_P) throw new Error("precommitment: not in 1..p-1");
  if (!Number.isSafeInteger(bytes) || bytes <= 0) throw new Error("bytes: not a positive whole number");
  return {
    receiver_id: vaultAccountId(vault, "vault"),
    method: VAULT_STORAGE_PREPAY.method,
    args: { precommitment: precommitment.toString() },
    deposit_yocto: BigInt(bytes) * VAULT_STORAGE_BYTE_COST,
  };
}

packages/kit/src/prover/prove.ts.body:
// One call from the device's leaves to a withdraw proof made in the prover worker (card vault-prover-e2e; the vault
// paper's rows V2.4 and V2.6, docs/plan1/vault.md l.1198 and l.1200, and the kit's call in l.1284: prove(inputs) ->
// {proof, publicSignals} in snarkjs JSON, in one same-origin worker, single thread).
//
// - The inputs are vaultWithdrawInput's (../vault/inputs.ts). It refuses, before any proof, a tree whose root is not
//   the vault's newest (a changed, missing or extra leaf), a note whose commitment or label is not in its tree, and
//   every withdrawal the vault would refuse. So a refused call never posts a prove to the worker.
// - The worker (client.ts, worker.js) loads the withdraw setup files once per Prover and checks each by sha256.
// - The worker's answer is checked here before the caller gets it: its public signals must be exactly the 8 this input
//   gives, computed apart from the circuit (Withdraw(32)'s outputs newCommitmentHash = Poseidon(value - withdrawn,
//   label, Poseidon(newNullifier, newSecret)) and existingNullifierHash = Poseidon(existingNullifier), commitment.circom
//   l.24-36 and withdraw.circom l.17-43 of Privacy Pools v1.3.0, then the input's public values, in
//   VAULT_WITHDRAW_SIGNALS order), and its proof must be in the affine form the vault parses (vaultProof). An answer
//   that differs is refused, so the proof the device hands on carries the roots, amount and context of its own request.
// - The pairing check is the vault's, with its compiled key: the page carries no verifier. prove-e2e.test.ts checks
//   the worker's proofs with snarkjs and the release's withdraw.vkey.
// Nothing here logs: the input holds the note's secrets.
import { poseidon1 } from "poseidon-lite/poseidon1";
import { poseidon2 } from "poseidon-lite/poseidon2";
import { poseidon3 } from "poseidon-lite/poseidon3";
import { poolWithdrawInput, type PoolWithdrawInputArgs, vaultWithdrawInput, type VaultWithdrawInput, type VaultWithdrawInputArgs } from "../vault/inputs.ts";
import { VAULT_WITHDRAW_SIGNALS, vaultProof, type VaultSnarkjsProof, type VaultWithdrawSignals } from "../vault/shapes.ts";
import type { Prover } from "./client.ts";

/** The worker's load and prove (startProver in client.ts gives one). */
export type VaultProver = Pick<Prover, "load" | "prove">;

/** A withdraw proof, its public signals in snarkjs order, and fullProve's own time in the worker, in ms. */
export type VaultWithdrawProof = { proof: VaultSnarkjsProof; publicSignals: VaultWithdrawSignals; proveMs: number };

// one load of the withdraw setup files per prover; a failed load is dropped, so the next call tries again
const loads = new WeakMap<VaultProver, Promise<void>>();
function loadWithdraw(prover: VaultProver): Promise<void> {
  const had = loads.get(prover);
  if (had) return had;
  const load = prover.load("withdraw");
  loads.set(prover, load);
  load.catch(() => {
    if (loads.get(prover) === load) loads.delete(prover);
  });
  return load;
}

/** The 8 public signals Withdraw(32) gives for this input, in snarkjs order. */
function signalsOf(i: VaultWithdrawInput): VaultWithdrawSignals {
  const left = BigInt(i.existingValue) - BigInt(i.withdrawnValue);
  const newCommitmentHash = poseidon3([left, BigInt(i.label), poseidon2([BigInt(i.newNullifier), BigInt(i.newSecret)])]);
  const existingNullifierHash = poseidon1([BigInt(i.existingNullifier)]);
  return [
    String(newCommitmentHash),
    String(existingNullifierHash),
    i.withdrawnValue,
    i.stateRoot,
    i.stateTreeDepth,
    i.ASPRoot,
    i.ASPTreeDepth,
    i.context,
  ];
}

/**
 * Proves the withdrawal of `args.withdrawn` from `args.note` in the prover worker, from the leaves the device holds
 * (`args.stateTree`, `args.labelTree`) against the vault's newest roots. Throws what vaultWithdrawInput refuses before
 * any proof, and refuses a worker answer whose public signals are not this input's or whose proof is not well formed.
 */
export async function vaultProveWithdraw(prover: VaultProver, args: VaultWithdrawInputArgs): Promise<VaultWithdrawProof> {
  return proveInput(prover, vaultWithdrawInput(args));
}

/**
 * The same for a spend in any pool on this circuit, with the context the pool's own context function gave
 * (poolWithdrawInput): the answer's 8 public signals must be this input's, its context the pool's.
 */
export async function poolProveWithdraw(prover: VaultProver, args: PoolWithdrawInputArgs): Promise<VaultWithdrawProof> {
  return proveInput(prover, poolWithdrawInput(args));
}

async function proveInput(prover: VaultProver, input: VaultWithdrawInput): Promise<VaultWithdrawProof> {
  const want = signalsOf(input);
  await loadWithdraw(prover);
  const got: unknown = await prover.prove("withdraw", input);
  const r = (got ?? {}) as { proof?: unknown; publicSignals?: unknown; proveMs?: unknown };
  const signals = r.publicSignals;
  if (!Array.isArray(signals) || signals.length !== want.length) throw new Error(`worker answer: not ${want.length} public signals`);
  want.forEach((w, k) => {
    if (signals[k] !== w) throw new Error(`worker answer: ${VAULT_WITHDRAW_SIGNALS[k]} is not the input's`);
  });
  try {
    vaultProof(r.proof as VaultSnarkjsProof);
  } catch (e) {
    throw new Error(`worker answer: ${e instanceof Error ? e.message : "proof: not snarkjs JSON"}`);
  }
  const proveMs = typeof r.proveMs === "number" && Number.isFinite(r.proveMs) ? r.proveMs : NaN;
  return { proof: r.proof as VaultSnarkjsProof, publicSignals: want, proveMs };
}

packages/kit/src/prover/client.ts.body:
// The prover's page side (vault.md 2.14, row V2.4), for SIGN_HOST only: APP_HOST's policy never allows
// 'wasm-unsafe-eval', so a prover there fails closed (M304 D-8; wallet.md 2.7). It starts the one same-origin worker,
// prover-worker.js (build.mjs), through the Trusted Types policy `prover-worker`, which turns exactly that one URL into a
// TrustedScriptURL and refuses every other (SIGN_HOST's CSP: require-trusted-types-for 'script'; trusted-types
// prover-worker). It fetches each setup file from its own origin at /assets/zk/<sha256>.<ext> (zk/setup-files.ts),
// always asking the server (cache "no-cache": SIGN_HOST caches the files immutable, so a file that once came back wrong
// under its pinned name would otherwise be read from the browser's cache at every retry; a right one costs a 304), and
// moves the bytes to the worker by transfer, so no copy stays here; the worker checks every file's size and sha256
// before snarkjs sees it (worker.js), and proves on its threads (worker.js, card signpage-prover-threads).
import { ZK_SETUP_FILES } from "../zk/setup-files.ts";
import type { VaultSnarkjsProof } from "../vault/shapes.ts";

export const PROVER_POLICY_NAME = "prover-worker";
/** Every refusal of a worker that died or was ended starts with this; such a worker answers nothing again. */
export const PROVER_DEAD_PREFIX = "prover worker: ";

/** True when `e` is the refusal of a dead or ended prover worker: start a new one to prove again. */
export function isProverDead(e: unknown): boolean {
  return e instanceof Error && e.message.startsWith(PROVER_DEAD_PREFIX);
}
export const PROVER_WORKER_PATH = "/prover-worker.js";

export type ProverCircuit = "withdraw" | "commitment";
export type ProverInput = Readonly<Record<string, string | readonly string[]>>;
export interface ProverResult {
  proof: VaultSnarkjsProof;
  publicSignals: string[];
  /** fullProve's own time in the worker, in ms. */
  proveMs: number;
}
export interface ProverViolation {
  directive: string;
  blocked: string;
  sample: string;
}
export interface Prover {
  /** Fetches the circuit's wasm and zkey and moves them to the worker, which refuses them unless both match their pins. */
  load(circuit: ProverCircuit): Promise<void>;
  prove(circuit: ProverCircuit, input: ProverInput): Promise<ProverResult>;
  terminate(): void;
}
export interface ProverOptions {
  /** CSP or Trusted Types violations the worker reports. */
  onViolation?: (v: ProverViolation) => void;
}

/** The setup file's address on the page's own origin. */
export function setupFileURL(name: "withdraw.wasm" | "withdraw.zkey" | "commitment.wasm" | "commitment.zkey", origin: string): string {
  // an own key only: a polluted Object.prototype names no file
  if (typeof name !== "string" || !Object.hasOwn(ZK_SETUP_FILES, name)) throw new Error(`no such setup file ${typeof name === "string" ? name : typeof name}`);
  const ext = name.slice(name.lastIndexOf(".") + 1);
  return new URL(`/assets/zk/${ZK_SETUP_FILES[name].sha256}.${ext}`, origin).href;
}

type ScriptURLPolicy = { createScriptURL(input: string): unknown };
let policy: ScriptURLPolicy | null = null;

/**
 * The worker's script URL made through the policy `prover-worker`, created once per page (the CSP names it without
 * 'allow-duplicates'). The policy throws on anything but this origin's PROVER_WORKER_PATH. In a browser without
 * Trusted Types the plain URL is returned, as nothing there checks a sink.
 */
export function proverWorkerScriptURL(): string | object {
  const origin = self.location.origin;
  const url = new URL(PROVER_WORKER_PATH, origin).href;
  const tt = (self as unknown as { trustedTypes?: { createPolicy(n: string, r: { createScriptURL(s: string): string }): ScriptURLPolicy } }).trustedTypes;
  if (!tt) return url;
  policy ??= tt.createPolicy(PROVER_POLICY_NAME, {
    createScriptURL(input: string): string {
      const u = new URL(input, self.location.origin);
      if (u.href !== url || u.origin !== self.location.origin) throw new TypeError(`${PROVER_POLICY_NAME} refuses ${u.href}`);
      return u.href;
    },
  });
  return policy.createScriptURL(url) as object;
}

type Reply = { id: number; ok: true; value: unknown } | { id: number; ok: false; error: string } | { type: "violation"; violation: ProverViolation };

/** Starts the prover worker on this page's origin. */
export function startProver(opts: ProverOptions = {}): Prover {
  const origin = self.location.origin;
  const worker = new Worker(proverWorkerScriptURL() as string, { name: "prover" });
  const pending = new Map<number, { resolve: (v: unknown) => void; reject: (e: Error) => void }>();
  let next = 1;
  let dead: Error | null = null;
  const failAll = (e: Error) => {
    dead = e;
    for (const p of pending.values()) p.reject(e);
    pending.clear();
  };
  worker.addEventListener("message", (ev: MessageEvent<Reply>) => {
    const m = ev.data;
    if ("type" in m) {
      if (m.type === "violation") opts.onViolation?.(m.violation);
      return;
    }
    const p = pending.get(m.id);
    if (!p) return;
    pending.delete(m.id);
    if (m.ok) p.resolve(m.value);
    else p.reject(new Error(m.error));
  });
  worker.addEventListener("error", (ev: ErrorEvent) => failAll(new Error(`${PROVER_DEAD_PREFIX}${ev.message || "failed to load"}`)));
  // a reply the page cannot deserialize would leave its call waiting for ever; no timeout, as a slow phone's proof is not a hang
  worker.addEventListener("messageerror", () => failAll(new Error(`${PROVER_DEAD_PREFIX}a reply could not be read`)));
  const call = (msg: Record<string, unknown>, transfer: Transferable[] = []): Promise<unknown> =>
    new Promise((resolve, reject) => {
      if (dead) return reject(dead);
      const id = next++;
      pending.set(id, { resolve, reject });
      worker.postMessage({ ...msg, id }, transfer);
    });

  const fetchFile = async (name: "withdraw.wasm" | "withdraw.zkey" | "commitment.wasm" | "commitment.zkey"): Promise<ArrayBuffer> => {
    const r = await fetch(setupFileURL(name, origin), { credentials: "omit", cache: "no-cache" });
    if (!r.ok) throw new Error(`${name}: HTTP ${r.status}`);
    return r.arrayBuffer();
  };

  return {
    async load(circuit) {
      const [wasm, zkey] = await Promise.all([fetchFile(`${circuit}.wasm`), fetchFile(`${circuit}.zkey`)]);
      await call({ cmd: "load", circuit, wasm, zkey }, [wasm, zkey]);
    },
    async prove(circuit, input) {
      return (await call({ cmd: "prove", circuit, input })) as ProverResult;
    },
    terminate() {
      worker.terminate();
      failAll(new Error(`${PROVER_DEAD_PREFIX}terminated`));
    },
  };
}

packages/kit/src/vault/inputs.ts.body:
// A withdrawal's proof inputs, built on the device from the leaves it holds (card vault-input-builder; the vault paper
// V2.6, docs/plan1/vault.md l.1198, withdraw part). The proof is Privacy Pools v1.3.0's Withdraw(32)
// (packages/circuits/circuits/withdraw.circom:17-43 at c312dcd), run by the pinned withdraw.wasm (../zk/setup-files.ts).
//
// - The trees: the vault's state tree (every commitment) and label tree (every deposit's and refund note's label) are
//   LeanIMTs hashed with circomlib's Poseidon(2) (vault.md l.95-96). The device keeps one VaultTree for each, built
//   once with @zk-kit/lean-imt (the TS tree VT-P01 checks against the vault's Rust port, vault.md l.1126) and
//   poseidon-lite's poseidon2, and appends each new page of leaves as it reads them, so a path never rehashes the tree.
// - The roots: the kit proves against the vault's newest roots (vault.md l.145-146), which the caller reads on two
//   RPCs. A tree whose root is not that root is refused: a stale prefix of leaves would prove an old root the vault
//   still accepts and that dates the read, and a forged leaf would make a proof the vault refuses.
// - The path: LeanIMT's proof leaves out every level where the node has no sibling (that level's node equals its child),
//   and its index holds only the kept levels' left/right bits. The circuit's LeanIMTInclusionProof walks maxDepth = 32
//   levels, takes bit i of the index for level i and passes the node up unchanged where siblings[i] is 0
//   (merkleTree.circom l.58-75, the pass-up rule l.74, sha256 5754b7b0). So the kept siblings go first, in order, and 0s
//   fill the rest up to 32; the index is LeanIMT's, never the leaf's position. Any other padding or order gives another
//   root and fails at witness time.
// - The context is computed here from the withdrawal the user made (shapes.ts vaultContextOf), after every check the
//   vault would make of it (vaultWithdrawalProblems), so recipient and fee are bound to what the user typed.
// - Field rule: every value is a field element in [0, p) and is refused otherwise, never reduced (poseidon-lite reduces
//   silently). A leaf is also never 0 (vault.md l.246, 2.5.1 row 10). A repeated leaf blocks only the note it is.
// - No tree holds 2^32 leaves (a JS array's length is below 2^32), so no depth is over 32.
// Nothing here logs: the note's secrets never leave the device.
import { keccak_256 } from "@noble/hashes/sha3.js";
import { LeanIMT } from "@zk-kit/lean-imt";
import { poseidon2 } from "poseidon-lite/poseidon2";
import { poseidon3 } from "poseidon-lite/poseidon3";
import {
  VAULT_CONSTANTS,
  VAULT_FIELD_P,
  vaultContextInput,
  vaultContextOf,
  vaultWithdrawalProblems,
  type VaultWithdrawal,
} from "./shapes.ts";

const DEPTH = VAULT_CONSTANTS.MAX_TREE_DEPTH;
const U128 = 1n << 128n;

/** A path as the circuit reads it: the root it proves, the tree's depth, LeanIMT's index and 32 siblings. */
export type VaultMerklePath = { root: bigint; depth: number; index: number; siblings: bigint[] };

function field(x: bigint, what: string): bigint {
  if (typeof x !== "bigint" || x < 0n || x >= VAULT_FIELD_P) throw new Error(`${what}: not a field element in [0, p)`);
  return x;
}

const hash = (a: bigint, b: bigint): bigint => poseidon2([a, b]);

/** A note's commitment, the leaf the vault and the pools write for it (commitment.circom:24-36): Poseidon(value, label,
 *  precommitment), each a field element, the value below 2^128. Needs no secret, so a reader of the chain can check a
 *  leaf against a deposit it names. */
export function vaultCommitment(value: bigint, label: bigint, precommitment: bigint): bigint {
  if (field(value, "value") >= U128) throw new Error("value: 2^128 or more");
  return poseidon3([value, field(label, "label"), field(precommitment, "precommitment")]);
}

/** One of the vault's two trees on the device: built once, then grown by each page of leaves read from the vault. */
export class VaultTree {
  #tree = new LeanIMT<bigint>(hash);
  #first = new Map<bigint, number>();
  #repeated = new Set<bigint>();

  constructor(leaves: readonly bigint[] = []) {
    if (leaves.length > 0) this.append(leaves);
  }

  get size(): number {
    return this.#tree.size;
  }
  get depth(): number {
    return this.#tree.depth;
  }
  /** The root, or undefined while the tree is empty. */
  get root(): bigint | undefined {
    return this.#tree.size === 0 ? undefined : this.#tree.root;
  }

  /** Appends the vault's next leaves, in insert order. A page with a leaf not in [1, p) changes nothing. */
  append(page: readonly bigint[]): void {
    if (!Array.isArray(page) || page.length === 0) throw new Error("page: no leaves");
    for (const [i, leaf] of page.entries()) {
      field(leaf, `page[${i}]`);
      if (leaf === 0n) throw new Error(`page[${i}]: a leaf is never 0`);
    }
    const start = this.#tree.size;
    this.#tree.insertMany([...page]);
    for (const [i, leaf] of page.entries()) {
      if (this.#first.has(leaf)) this.#repeated.add(leaf);
      else this.#first.set(leaf, start + i);
    }
  }

  /** The circuit's path for `leaf`: LeanIMT's siblings then 0s up to 32, and LeanIMT's index. */
  path(leaf: bigint): VaultMerklePath {
    const at = this.#first.get(field(leaf, "leaf"));
    if (at === undefined) throw new Error("leaf: not in the tree");
    if (this.#repeated.has(leaf)) throw new Error("leaf: repeats in the tree");
    const p = this.#tree.generateProof(at);
    const siblings = [...p.siblings, ...Array<bigint>(DEPTH - p.siblings.length).fill(0n)];
    return { root: this.#tree.root, depth: this.#tree.depth, index: p.index, siblings };
  }
}

/** The root the circuit computes from a path (merkleTree.circom l.58-75), for checking a path on the device. */
export function vaultRootOfPath(leaf: bigint, index: number, siblings: readonly bigint[]): bigint {
  if (siblings.length !== DEPTH) throw new Error(`siblings: not ${DEPTH} of them`);
  if (!Number.isSafeInteger(index) || index < 0 || index >= 2 ** DEPTH) throw new Error("index: not below 2^32");
  let node = field(leaf, "leaf");
  for (let i = 0; i < DEPTH; i++) {
    const s = field(siblings[i]!, `siblings[${i}]`);
    if (s === 0n) continue;
    node = Math.floor(index / 2 ** i) % 2 === 1 ? hash(s, node) : hash(node, s);
  }
  return node;
}

/** Withdraw(32)'s `signal input`s, every value a decimal string, as snarkjs reads them. */
export type VaultWithdrawInput = {
  withdrawnValue: string;
  stateRoot: string;
  stateTreeDepth: string;
  ASPRoot: string;
  ASPTreeDepth: string;
  context: string;
  label: string;
  existingValue: string;
  existingNullifier: string;
  existingSecret: string;
  newNullifier: string;
  newSecret: string;
  stateSiblings: string[];
  stateIndex: string;
  ASPSiblings: string[];
  ASPIndex: string;
};

/** What the device knows when it spends a note. */
export type VaultWithdrawInputArgs = {
  /** The device's state tree and label tree, holding every leaf the vault has. */
  stateTree: VaultTree;
  labelTree: VaultTree;
  /** The vault's newest state root and label root, read on two RPCs. */
  newestStateRoot: bigint;
  newestLabelRoot: bigint;
  /** The note spent: its value and label from the vault, its secrets from the 12 words. */
  note: { value: bigint; label: bigint; nullifier: bigint; secret: bigint };
  /** The change note's secrets (value = note.value - withdrawn, same label). */
  newNullifier: bigint;
  newSecret: bigint;
  withdrawn: bigint;
  /** The withdrawal the user made, the vault's account id, its scope, and the time now in ms. */
  withdrawal: VaultWithdrawal;
  vaultId: string;
  scope: bigint;
  nowMs: number;
};

/**
 * Withdraw(32)'s inputs to spend `note`, withdrawing `withdrawn` and leaving the rest as a change note under the same
 * label. Refuses what the circuit or the vault would refuse, before the device spends a proof on it: a withdrawal
 * vaultWithdrawalProblems names, a tree whose root is not the vault's newest, a note whose commitment is not in the
 * state tree or whose label is not in the label tree (or repeats there), withdrawn over the note's value, a value of
 * 2^128 or more, the change nullifier equal to the spent one, and any value not below p.
 */
export function vaultWithdrawInput(a: VaultWithdrawInputArgs): VaultWithdrawInput {
  const scope = field(a.scope, "scope");
  const { withdrawal, vaultId, nowMs, scope: _scope, ...rest } = a;
  const problems = vaultWithdrawalProblems(withdrawal, field(a.withdrawn, "withdrawn"), vaultId, nowMs);
  if (problems.length > 0) throw new Error(`withdrawal: ${problems.join("; ")}`);
  return poolWithdrawInput({ ...rest, context: vaultContextOf(keccak_256, vaultContextInput(vaultId, withdrawal), scope) });
}

/**
 * What the device knows when it spends a note in any pool on this circuit (the NEAR vault, the Solana and EVM pools):
 * the same as VaultWithdrawInputArgs, with the context the pool's own context function computed in place of the
 * vault's withdrawal, account id, scope and time. The pool checks its own request fields before it gives the context.
 */
export type PoolWithdrawInputArgs = Omit<VaultWithdrawInputArgs, "withdrawal" | "vaultId" | "scope" | "nowMs"> & { context: bigint };

/**
 * Withdraw(32)'s inputs for a spend in any pool, against the pool's newest roots, with the pool's context as the 8th
 * public signal. Refuses what vaultWithdrawInput refuses, the vault's withdrawal checks aside but withdrawn 0, and a
 * context not below p.
 */
export function poolWithdrawInput(a: PoolWithdrawInputArgs): VaultWithdrawInput {
  const value = field(a.note.value, "note.value");
  const label = field(a.note.label, "note.label");
  const nullifier = field(a.note.nullifier, "note.nullifier");
  const secret = field(a.note.secret, "note.secret");
  const newNullifier = field(a.newNullifier, "newNullifier");
  const newSecret = field(a.newSecret, "newSecret");
  const withdrawn = field(a.withdrawn, "withdrawn");
  const context = field(a.context, "context");
  if (value >= U128) throw new Error("note.value: 2^128 or more");
  if (withdrawn === 0n) throw new Error("withdrawn: 0"); // the vault refuses it (vaultWithdrawalProblems)
  if (withdrawn > value) throw new Error("withdrawn: over the note's value");
  if (newNullifier === nullifier) throw new Error("newNullifier: equals the spent note's nullifier");

  if (a.stateTree.root !== field(a.newestStateRoot, "newestStateRoot")) throw new Error("stateTree: its root is not the vault's newest");
  if (a.labelTree.root !== field(a.newestLabelRoot, "newestLabelRoot")) throw new Error("labelTree: its root is not the vault's newest");
  // commitment.circom:24-36: commitment = Poseidon(value, label, Poseidon(nullifier, secret))
  const commitment = vaultCommitment(value, label, poseidon2([nullifier, secret]));
  const s = pathOf(a.stateTree, commitment, "the note's commitment");
  const l = pathOf(a.labelTree, label, "the note's label");

  return {
    withdrawnValue: String(withdrawn),
    stateRoot: String(s.root),
    stateTreeDepth: String(s.depth),
    ASPRoot: String(l.root),
    ASPTreeDepth: String(l.depth),
    context: String(context),
    label: String(label),
    existingValue: String(value),
    existingNullifier: String(nullifier),
    existingSecret: String(secret),
    newNullifier: String(newNullifier),
    newSecret: String(newSecret),
    stateSiblings: s.siblings.map(String),
    stateIndex: String(s.index),
    ASPSiblings: l.siblings.map(String),
    ASPIndex: String(l.index),
  };
}

function pathOf(t: VaultTree, leaf: bigint, what: string): VaultMerklePath {
  try {
    return t.path(leaf);
  } catch (e) {
    throw new Error(`${what}: ${e instanceof Error ? e.message : String(e)}`);
  }
}

packages/kit/src/vault/sync.ts.body:
// The vault's pages, read on two RPCs and matched on the device (card vault-kit-sync; the vault paper V4.1, 2.5.6 and
// 2.10 (c), docs/plan1/vault.md l.1230, l.492-501, l.674-676). Every list the vault pages (deposits, spends, leaves,
// labels) and both trees' heads, read from a cursor so a caller resumes where it stopped instead of from 0.
//
// - One block on both RPCs. Each RPC's final height is read first (state_tree at final); every read after it names
//   the lower of the two by block_id, so two honest RPCs answer the same state and any difference is a lie or a fault,
//   never lag. An RPC ahead of the other only waits: its newer rows come in the next sync. Both answers must carry
//   that height and the same block hash. Final heights more than VAULT_SYNC_LAG_MAX (the device's window W) apart
//   stop the sync ("lag"): one RPC is stuck or lying, and a read at its height would be stale. A caller that needs a
//   block at or above a height (a signed call's max_block_height + 5) puts it in cursor.height ("behind" below it).
// - Byte for byte. Each view's answer bytes must be equal on both RPCs (vault paper 2.12 step 2), else the sync stops
//   (VaultSyncStopped "disagree"): an extra, missing or changed row on one RPC, a tree head that differs, another
//   block. One RPC down, or an answer that is not a view result, stops it too ("rpc"). Nothing is returned from a
//   stopped sync and the caller's cursor is never changed, so a stop costs a read again, never a row.
// - Rows as the vault writes them. Every row is checked as contracts/vault/src/lib.rs's views write it: its exact
//   fields, in its order, once each, compact, so the answer must be the bytes the vault's serializer writes for
//   the rows parsed from it; its index at its place, decimals canonical and below p, amounts u128, account ids NEAR
//   ids ("row").
// - The cursor moves only past rows both RPCs gave. A reported count never moves it: the leaves and labels read must
//   end at their tree's size, which both RPCs gave equal ("count" otherwise, and for a cursor past that size), and the
//   deposits and spends cursors move by the rows read; a deposits or spends cursor c > 0 that reads no row must find
//   row c - 1 ("count" otherwise), so a cursor past the list's end never skips the rows written later. Every list is
//   append-only (2.5.6), so the rows below a cursor never change, with one exception: a spend's status and refund
//   fields change until it is settled (2.5.5), so the spends cursor stops at the first spend not settled and the next
//   sync reads it again (a row read again replaces the earlier copy, by its index).
// - No lookup of one secret-derived value: whole pages only, matched here (2.5.6). Deposits are confirmed from these
//   rows, never from a transaction read by hash (2.10 (c)).
// - Pages any public RPC serves (review R-03): each list starts at VAULT_SYNC_PAGE rows, about 125 Tgas a view; a page
//   an RPC refuses as too heavy is read again at half its rows on both RPCs (at most three times), so the list still
//   reads whole, and a busy answer is asked again after a wait (VAULT_SYNC_BUSY_WAITS_MS).
// - An abort ends the sync at once, even inside a read an RPC never answers; the signal goes to the RPC's query too.
// The kit names no provider: the caller passes two RPCs of different operators (the wallet's NEAR_NETWORKS pair).
import { VAULT_CONSTANTS, VAULT_FIELD_P, vaultAccountId, vaultDecimal, type VaultSpendStatus } from "./shapes.ts";
import { deepFreeze } from "../freeze.ts";

/**
 * A NEAR JSON-RPC provider's `query` method: the params of one query, its whole JSON-RPC answer. The signal is the
 * sync's; a provider may end its request on it (the sync stops waiting on its own either way).
 */
export interface VaultSyncRpc {
  name: string;
  query(params: Record<string, unknown>, signal?: AbortSignal): Promise<unknown>;
}

/**
 * The most the two RPCs' final heights may differ, in blocks: the device's window W, 120 blocks or about 70 s (vault
 * paper 2.10 (b), docs/plan1/vault.md l.670-672). Two honest RPCs differ by a block or two.
 */
export const VAULT_SYNC_LAG_MAX = 120;

/** The lists the vault pages (2.5.6). */
export const VAULT_SYNC_LISTS = ["deposits", "spends", "leaves", "labels"] as const;
deepFreeze(VAULT_SYNC_LISTS);
export type VaultSyncList = (typeof VAULT_SYNC_LISTS)[number];

/**
 * Each list's first page, in rows: as many as one view call can carry at about 125 Tgas (vault review R-03,
 * research docs/reviews/vault-review-opus-contract.md l.45). The view caps:
 * - The protocol's is 1,000 Tgas today; it was 200 Tgas, then 300 from protocol 52, then 1,000 from 83 (near-parameters
 *   0.37.4 res/runtime_configs/52.yaml l.2, 83.yaml l.8, parameters.snap l.203). A node can set its own lower one
 *   (near-chain-configs 0.37.4 client_config.rs l.836, max_gas_burnt_view).
 * - On the six RPCs the kit and the exit tool list (NEAR_NETWORKS, EXIT_NETWORKS), a view that grows with its input
 *   gave the same cap: social's get with K copies of one empty key passed at K = 15,412 to 15,429 and stopped at
 *   15,451 to 15,546 on every one, testnet and mainnet (read 2026-11-06 05:48-05:49Z). So none of them caps below
 *   the others. The lowest cap any nearcore has had is 200 Tgas, so 125 Tgas leaves over a third of it spare.
 * The gas per page was measured with the release build in near-sandbox 2.13.4, with each list's largest rows, by vault
 * review R-03 (its probe stays with the review; contracts/vault/tests/s12.rs measures every view per row in the tree):
 * - spends: 250 rows 125.135 Tgas, measured (500 rows 249.148, 1,000 rows 497.053), so 250;
 * - deposits: 1,000 rows 276.385 Tgas, at most 0.277 a row with the call's own cost in it, so 450 (at most 124.4);
 * - leaves: 1,000 rows 162.548 Tgas, at most 0.163 a row, so 750 (at most 121.9);
 * - labels: the same view code as leaves (lib.rs `labels` and `leaves` are both tree_page), so 750.
 * A page an RPC still refuses as too heavy (vaultViewTooHeavy) is read again at half its rows, at most three times:
 * a page of VAULT_SYNC_PAGE[list] / 8 rows refused stops the sync, naming the RPC, since an RPC that caps that low
 * would turn a long list into days of reads.
 */
export const VAULT_SYNC_PAGE: Readonly<Record<VaultSyncList, number>> = /* @__PURE__ */ Object.freeze({ deposits: 450, spends: 250, leaves: 750, labels: 750 });

/**
 * Whether one RPC's answer to a view refuses it as too heavy, so the same rows read in a smaller page can pass:
 * nearcore's gas cap, `result.error` "wasm execution failed with error: HostError(GasLimitExceeded)" at HTTP 200, the
 * exact answer of all six listed RPCs to a view over the cap (read 2026-11-06 05:47-05:49Z on both FastNEAR URLs and
 * the dRPC URL of each network in NEAR_NETWORKS). Any other answer is not this one: another error stops the read as
 * before.
 */
export function vaultViewTooHeavy(a: unknown): boolean {
  return isObj(a) && isObj(a.result) && typeof a.result.error === "string" && a.result.error.includes("HostError(GasLimitExceeded)");
}

/**
 * Whether one RPC's answer says it is busy, so the same view asked again later can pass: dRPC's free plan's timeout,
 * HTTP 408 with `error.code` 30 and "Request timeout on the free plan, please upgrade to paid plan" (near.drpc.org and
 * near-testnet.drpc.org, read 2026-11-06 05:47Z; the RPC adapters nearRpc and exitRpc give that body back rather than
 * throw on it). It comes from the provider's load, not the page's size (a review's 14 near-cap views on dRPC answered
 * at HTTP 200), so the read asks for the same page again after each of VAULT_SYNC_BUSY_WAITS_MS, then stops.
 */
export function vaultViewBusy(a: unknown): boolean {
  return isObj(a) && isObj(a.error) && a.error.code === 30 && typeof a.error.message === "string" && a.error.message.startsWith("Request timeout on the free plan");
}

/** The waits, in ms, before each time a busy answer (vaultViewBusy) is asked again: three tries more, then a stop. */
export const VAULT_SYNC_BUSY_WAITS_MS: readonly number[] = /* @__PURE__ */ Object.freeze([250, 500, 1_000]);

/**
 * Where the next sync starts: per list, the first row it reads; the height the last sync read at, which the next must
 * not be below. JSON numbers only, so a caller stores it as is.
 */
export type VaultSyncCursor = { vault: string; height: number } & Record<VaultSyncList, number>;

/** The cursor of a vault never read: every list from 0. */
export function vaultSyncStart(vault: string): VaultSyncCursor {
  return { vault: vaultAccountId(vault, "vault"), height: 0, deposits: 0, spends: 0, leaves: 0, labels: 0 };
}

/** A row of the deposits view (DepositView). */
export type VaultDepositRow = { index: number; precommitment: bigint; label: bigint; value: bigint; leafIndex: bigint; depositor: string };
/** A row of the spends view (SpendView): the spend, its request data and its refund note's fields. */
export type VaultSpendRow = {
  index: number;
  nullifierHash: bigint;
  withdrawn: bigint;
  newLeafIndex: bigint;
  refundPrecommitment: bigint;
  refundValue: bigint;
  refundLabel: bigint;
  refundLeafIndex: bigint;
  status: VaultSpendStatus;
  payer: string;
  reserve: bigint;
  recipient: string;
  fee: bigint;
  context: bigint;
};
/** state_tree() or label_tree(). */
export type VaultTreeHead = { size: number; depth: number; root: bigint };

export type VaultSyncResult = {
  /** The block every read named, on both RPCs. */
  height: number;
  blockHash: string;
  stateTree: VaultTreeHead;
  labelTree: VaultTreeHead;
  /** Each list's rows from the cursor given to its end at `height`; a list not asked for is empty. */
  deposits: VaultDepositRow[];
  spends: VaultSpendRow[];
  /** Leaves and labels from the cursor's leaves and labels index on. */
  leaves: bigint[];
  labels: bigint[];
  /** The next sync's start. */
  cursor: VaultSyncCursor;
};

export type VaultSyncStopCode = "input" | "rpc" | "disagree" | "row" | "count" | "behind" | "lag";
export class VaultSyncStopped extends Error {
  readonly code: VaultSyncStopCode;
  constructor(code: VaultSyncStopCode, detail: string) {
    super(`vault sync stopped (${code}): ${detail}`);
    this.name = "VaultSyncStopped";
    this.code = code;
  }
}

export type VaultSyncArgs = {
  vault: string;
  /** Two RPCs of different operators. */
  rpcs: readonly [VaultSyncRpc, VaultSyncRpc];
  /** vaultSyncStart(vault) on a first read; else the cursor the last sync returned. */
  cursor: VaultSyncCursor;
  /** The lists to read; all four unless given. Lists not read keep their cursor. */
  lists?: readonly VaultSyncList[];
  signal?: AbortSignal;
};

/** Reads the vault's pages from `cursor` on both RPCs at one block and returns the rows both gave, byte for byte. */
export async function vaultSync(args: VaultSyncArgs): Promise<VaultSyncResult> {
  const { vault, rpcs, cursor, signal } = args;
  const lists = args.lists ?? VAULT_SYNC_LISTS;
  checkInput(vault, rpcs, cursor, lists);

  // The two final heights; every read after this one names the lower.
  signal?.throwIfAborted();
  const probe = call(vault, "state_tree", {}, { finality: "final" });
  const finals = await Promise.all([answer(rpcs[0], probe, signal), answer(rpcs[1], probe, signal)]);
  if (Math.abs(finals[0].height - finals[1].height) > VAULT_SYNC_LAG_MAX)
    throw new VaultSyncStopped("lag", `the RPCs' final heights ${finals[0].height} and ${finals[1].height} are over ${VAULT_SYNC_LAG_MAX} blocks apart`);
  const height = Math.min(finals[0].height, finals[1].height);
  if (height < cursor.height) throw new VaultSyncStopped("behind", `the RPCs' final height ${height} is below the cursor's ${cursor.height}`);

  let blockHash = "";
  const read = async (method: string, a: Record<string, number>): Promise<unknown> => {
    signal?.throwIfAborted();
    const at = call(vault, method, a, { block_id: height });
    const [x, y] = await Promise.all([answer(rpcs[0], at, signal), answer(rpcs[1], at, signal)]);
    if (x.height !== height || y.height !== height) throw new VaultSyncStopped("rpc", `${method}: an answer not at block ${height}`);
    if (x.hash !== y.hash || (blockHash !== "" && x.hash !== blockHash)) throw new VaultSyncStopped("disagree", `${method}: two blocks at height ${height}`);
    blockHash = x.hash;
    if (!sameBytes(x.bytes, y.bytes)) throw new VaultSyncStopped("disagree", `${method}(${JSON.stringify(a)}): the RPCs' answers differ`);
    let text: string;
    try {
      text = new TextDecoder("utf-8", { fatal: true, ignoreBOM: true }).decode(x.bytes);
    } catch {
      throw new VaultSyncStopped("row", `${method}: not UTF-8`);
    }
    let value: unknown;
    try {
      value = JSON.parse(text);
    } catch {
      throw new VaultSyncStopped("row", `${method}: not JSON`);
    }
    if (JSON.stringify(inVaultOrder(method, value)) !== text)
      throw new VaultSyncStopped("row", `${method}: not the vault's own bytes (field order, a repeated field, spacing or a number's form)`);
    return value;
  };

  const stateTree = head(await read("state_tree", {}), "state_tree");
  const labelTree = head(await read("label_tree", {}), "label_tree");
  const next: VaultSyncCursor = { ...cursor, height };
  const out: VaultSyncResult = { height, blockHash, stateTree, labelTree, deposits: [], spends: [], leaves: [], labels: [], cursor: next };

  for (const list of VAULT_SYNC_LISTS) {
    if (!lists.includes(list)) continue;
    const from = cursor[list];
    const size = list === "leaves" ? stateTree.size : list === "labels" ? labelTree.size : null;
    const rows: unknown[] = [];
    // A page an RPC refuses as too heavy is read again at half its rows, on both RPCs, so both still answer the same
    // rows; the smaller page holds for the rest of this list. A page of an eighth of the first refused stops the sync.
    let limit = VAULT_SYNC_PAGE[list];
    const floor = Math.floor(VAULT_SYNC_PAGE[list] / 8);
    for (let at = from; ; ) {
      let page: unknown;
      try {
        page = await read(list, { from: at, limit });
      } catch (e) {
        if (!(e instanceof TooHeavy)) throw e;
        if (limit <= floor) throw new VaultSyncStopped("rpc", `${e.detail}, even at ${limit} rows`);
        limit = Math.floor(limit / 2);
        continue;
      }
      if (!Array.isArray(page) || page.length > limit) throw new VaultSyncStopped("row", `${list}: not a page`);
      page.forEach((x, k) => rows.push(parseRow(list, x, at + k)));
      if (page.length < limit) break;
      at += limit;
    }
    // A deposits or spends cursor past the list's end would read no row and wait there, skipping every row written
    // below it later: an empty read from c > 0 must find row c - 1.
    if (size === null && rows.length === 0 && from > 0) {
      const last = await read(list, { from: from - 1, limit: 1 });
      if (!Array.isArray(last) || last.length !== 1) throw new VaultSyncStopped("count", `${list}: the cursor ${from} is past the list's end`);
      parseRow(list, last[0], from - 1);
    }
    const end = from + rows.length; // a cursor past the list's end reads no row, so it ends past the tree's size too
    if (size !== null && end !== size) throw new VaultSyncStopped("count", `${list}: the pages end at ${end}, the tree's size is ${size}`);
    if (list === "deposits") out.deposits = rows as VaultDepositRow[];
    else if (list === "spends") out.spends = rows as VaultSpendRow[];
    else out[list] = rows as bigint[];
    // A spend can change until it is settled: the next sync starts at the first one that is not.
    const open = list === "spends" ? out.spends.findIndex((s) => s.status !== "settled") : -1;
    next[list] = open === -1 ? end : from + open;
  }
  return out;
}

// ---------- reads ----------
type Obj = Record<string, unknown>;
const isObj = (x: unknown): x is Obj => typeof x === "object" && x !== null && !Array.isArray(x);

function call(vault: string, method: string, a: Record<string, number>, at: { finality: "final" } | { block_id: number }): Obj {
  return { request_type: "call_function", account_id: vault, method_name: method, args_base64: btoa(JSON.stringify(a)), ...at };
}

/** One RPC's answer to one view call: its bytes, height and block hash, or a stop ("rpc"). */
async function answer(rpc: VaultSyncRpc, params: Obj, signal?: AbortSignal): Promise<{ bytes: Uint8Array; height: number; hash: string }> {
  let a: unknown;
  for (let tries = 0; ; tries++) {
    try {
      a = await untilAbort(rpc.query(params, signal), signal);
    } catch (e) {
      if (signal?.aborted) throw signal.reason;
      throw new VaultSyncStopped("rpc", `${rpc.name}: ${e instanceof Error ? e.message : String(e)}`);
    }
    if (!vaultViewBusy(a)) break;
    const wait = VAULT_SYNC_BUSY_WAITS_MS[tries];
    if (wait === undefined) throw new VaultSyncStopped("rpc", `${rpc.name}: ${String(params.method_name)}: busy (a free-plan timeout) ${tries + 1} times`);
    await untilAbort(new Promise((ok) => setTimeout(ok, wait)), signal);
  }
  if (vaultViewTooHeavy(a)) throw new TooHeavy(`${rpc.name}: ${String(params.method_name)}: refused as too heavy`);
  const r = isObj(a) && a.error === undefined ? a.result : undefined;
  const bytes = isObj(r) && r.error === undefined ? r.result : undefined;
  if (
    !isObj(r) ||
    !Number.isSafeInteger(r.block_height) ||
    (r.block_height as number) <= 0 ||
    typeof r.block_hash !== "string" ||
    !Array.isArray(bytes) ||
    !bytes.every((b) => Number.isInteger(b) && b >= 0 && b <= 255)
  )
    throw new VaultSyncStopped("rpc", `${rpc.name}: ${String(params.method_name)}: not a view result`);
  return { bytes: Uint8Array.from(bytes as number[]), height: r.block_height as number, hash: r.block_hash };
}

/**
 * An RPC's answer that a view is too heavy (vaultViewTooHeavy): a stop ("rpc") like any other, except that a list read
 * of more than one row catches it and halves its page.
 */
class TooHeavy extends VaultSyncStopped {
  readonly detail: string;
  constructor(detail: string) {
    super("rpc", detail);
    this.detail = detail;
  }
}

/** p, or the signal's reason once it aborts, whichever comes first. */
function untilAbort<T>(p: Promise<T>, signal?: AbortSignal): Promise<T> {
  if (!signal) return p;
  return new Promise<T>((resolve, reject) => {
    const stop = () => reject(signal.reason);
    if (signal.aborted) return stop();
    signal.addEventListener("abort", stop, { once: true });
    p.then(resolve, reject).finally(() => signal.removeEventListener("abort", stop));
  });
}

function sameBytes(a: Uint8Array, b: Uint8Array): boolean {
  return a.length === b.length && a.every((v, i) => v === b[i]);
}

function checkInput(vault: string, rpcs: readonly [VaultSyncRpc, VaultSyncRpc], cursor: VaultSyncCursor, lists: readonly VaultSyncList[]): void {
  const no = (d: string) => new VaultSyncStopped("input", d);
  try {
    vaultAccountId(vault, "vault");
  } catch (e) {
    throw no((e as Error).message);
  }
  if (!Array.isArray(rpcs) || rpcs.length !== 2 || !rpcs.every((r) => isObj(r) && typeof r.query === "function" && typeof r.name === "string"))
    throw no("two RPCs, each with a name and query");
  if (rpcs[0] === rpcs[1] || rpcs[0].name === rpcs[1].name) throw no("the two RPCs are one");
  if (!isObj(cursor) || cursor.vault !== vault) throw no("the cursor is not this vault's");
  for (const k of ["height", ...VAULT_SYNC_LISTS] as const) if (!Number.isSafeInteger(cursor[k]) || cursor[k] < 0) throw no(`cursor.${k}: not a whole number`);
  if (!Array.isArray(lists) || !lists.every((l) => (VAULT_SYNC_LISTS as readonly string[]).includes(l))) throw no(`lists: only ${VAULT_SYNC_LISTS.join(", ")}`);
}

// ---------- rows, as the vault's views write them (contracts/vault/src/lib.rs) ----------
const DEPOSIT_FIELDS = ["index", "precommitment", "label", "value", "leaf_index", "depositor"];
const SPEND_FIELDS = [
  "index",
  "nullifier_hash",
  "withdrawn",
  "new_leaf_index",
  "refund_precommitment",
  "refund_value",
  "refund_label",
  "refund_leaf_index",
  "status",
  "payer",
  "reserve",
  "recipient",
  "fee",
  "context",
];
const TREE_FIELDS = ["size", "depth", "root"];
const STATUSES: readonly VaultSpendStatus[] = ["in_flight", "paid", "refund_pending", "settled"];

/** A view's value with each object's fields in the vault's struct order, as its serializer writes them. */
function inVaultOrder(method: string, v: unknown): unknown {
  const order = method === "deposits" ? DEPOSIT_FIELDS : method === "spends" ? SPEND_FIELDS : method.endsWith("_tree") ? TREE_FIELDS : null;
  if (order === null) return v;
  const pick = (o: unknown) => (isObj(o) ? Object.fromEntries(order.map((k) => [k, o[k]])) : o);
  return Array.isArray(v) ? v.map(pick) : pick(v);
}

function parseRow(list: VaultSyncList, x: unknown, at: number): unknown {
  try {
    if (list === "leaves" || list === "labels") return field(x, "leaf");
    const o = fields(x, list === "deposits" ? DEPOSIT_FIELDS : SPEND_FIELDS);
    if (o.index !== at) throw new Error(`index ${String(o.index)} at ${at}`);
    if (list === "deposits")
      return {
        index: at,
        precommitment: field(o.precommitment, "precommitment"),
        label: field(o.label, "label"),
        value: u128(o.value, "value"),
        leafIndex: u64(o.leaf_index, "leaf_index"),
        depositor: vaultAccountId(o.depositor as string, "depositor"),
      } satisfies VaultDepositRow;
    if (!STATUSES.includes(o.status as VaultSpendStatus)) throw new Error("status: not a spend status");
    return {
      index: at,
      nullifierHash: field(o.nullifier_hash, "nullifier_hash"),
      withdrawn: u128(o.withdrawn, "withdrawn"),
      newLeafIndex: u64(o.new_leaf_index, "new_leaf_index"),
      refundPrecommitment: field(o.refund_precommitment, "refund_precommitment"),
      refundValue: u128(o.refund_value, "refund_value"),
      refundLabel: field(o.refund_label, "refund_label"),
      refundLeafIndex: u64(o.refund_leaf_index, "refund_leaf_index"),
      status: o.status as VaultSpendStatus,
      payer: vaultAccountId(o.payer as string, "payer"),
      reserve: u128(o.reserve, "reserve"),
      recipient: vaultAccountId(o.recipient as string, "recipient"),
      fee: u128(o.fee, "fee"),
      context: field(o.context, "context"),
    } satisfies VaultSpendRow;
  } catch (e) {
    throw new VaultSyncStopped("row", `${list} row ${at}: ${(e as Error).message}`);
  }
}

function head(x: unknown, what: string): VaultTreeHead {
  try {
    const o = fields(x, TREE_FIELDS);
    const depth = o.depth;
    if (!Number.isSafeInteger(depth) || (depth as number) < 0 || (depth as number) > VAULT_CONSTANTS.MAX_TREE_DEPTH) throw new Error("depth");
    return { size: Number(u64(o.size, "size")), depth: depth as number, root: field(o.root, "root") };
  } catch (e) {
    throw new VaultSyncStopped("row", `${what}: ${(e as Error).message}`);
  }
}

/** An object with every one of these fields (an extra, repeated or reordered field is refused before, by the bytes check in read). */
function fields(x: unknown, names: readonly string[]): Obj {
  if (!isObj(x)) throw new Error("not an object");
  const keys = Object.keys(x);
  if (!names.every((n) => keys.includes(n))) throw new Error(`fields: not ${names.join(", ")}`);
  return x;
}
function field(x: unknown, what: string): bigint {
  const n = vaultDecimal(x as string, what);
  if (n >= VAULT_FIELD_P) throw new Error(`${what}: not below p`);
  return n;
}
function u128(x: unknown, what: string): bigint {
  const n = vaultDecimal(x as string, what);
  if (n >= 1n << 128n) throw new Error(`${what}: not a u128`);
  return n;
}
/** A u64 the vault writes as a JSON number: a safe integer here, since every index is below 2^53. */
function u64(x: unknown, what: string): bigint {
  if (!Number.isSafeInteger(x) || (x as number) < 0) throw new Error(`${what}: not a whole number`);
  return BigInt(x as number);
}

