      adapters: bare({ v3: "0x1e62242773f696271b0cc3029b8672c385b7ce45", v4: "0x9d040a025689a10872f0f2f8b581135dde52ca6f" }),
      sellDelegate: "0xe3223113781f527188f634615ad9a3ca0aa20a4d",
